# SPDX-License-Identifier: MIT
# Weather data from Open-Meteo (https://open-meteo.com: no account, no key, free for
# non-commercial use) and the app's settings in the "weather" section of settings.json.
#
# On a Linux board curl downloads in the background (mpy_wifi.Job): start a request, then call
# poll() from a timer until it returns the data. In the Studio simulator there is no network:
# demo data comes back at once.

import json

try:
    import mpy_settings
    import mpy_wifi
except ImportError:
    mpy_settings = mpy_wifi = None

UNITS = (("C", "celsius"), ("F", "fahrenheit"))
WINDS = (("km/h", "kmh"), ("m/s", "ms"), ("mph", "mph"), ("kn", "kn"))
REFRESH_MINUTES = (15, 30, 60)
DEFAULTS = {
    "place": "", "latitude": None, "longitude": None,
    "units": 0, "wind": 0, "refresh": 1,
    # dimmed from 23:00 to 05:30, half hours counted from midnight
    "night_from": 46, "night_to": 11, "night_level": 20,
}
_demo_settings = {}


# curl's exit codes a board meets most, in words.
CURL_ERRORS = {
    6: "name not found: is the network up?",
    7: "cannot connect to the server",
    28: "the server did not answer in time",
    60: "certificate refused: is the clock set? (NTP after power-on)",
}


def settings():
    stored = (mpy_settings.get("weather") if mpy_settings else _demo_settings.get("weather")) or {}
    values = dict(DEFAULTS)
    values.update(stored)
    return values


def save(values):
    if mpy_settings:
        mpy_settings.update("weather", values)
    else:
        _demo_settings["weather"] = values


def _quote(text):
    out = ""
    for byte in text.encode():
        c = chr(byte)
        out += c if (c.isalpha() and byte < 128) or c.isdigit() else "%%%02X" % byte
    return out


class Request:
    # A download in the background. poll(): None while it runs, then (data, error).
    def __init__(self, url, demo):
        self._demo = demo
        self._job = mpy_wifi.Job(["curl", "-s", "-f", "-m", "20", url]) if mpy_wifi else None

    def poll(self):
        if self._job is None:
            return self._demo, None
        if self._job.poll() is None:
            return None
        if self._job.status != 0:
            return None, CURL_ERRORS.get(self._job.status, "no answer (curl %d)" % self._job.status)
        try:
            return json.loads(self._job.output.replace(b"\r", b"").decode()), None
        except ValueError:
            return None, "bad answer"


def forecast(values):
    url = ("https://api.open-meteo.com/v1/forecast?latitude=%.4f&longitude=%.4f&timezone=auto"
           "&forecast_days=5&temperature_unit=%s&wind_speed_unit=%s"
           "&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,"
           "wind_speed_10m,is_day"
           "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max"
           ) % (values["latitude"], values["longitude"], UNITS[values["units"]][1], WINDS[values["wind"]][1])
    return Request(url, DEMO_FORECAST)


def geocode(name):
    url = ("https://geocoding-api.open-meteo.com/v1/search?count=8&language=en&format=json&name="
           + _quote(name))
    return Request(url, {"results": [
        {"name": "Demo City", "country": "Demo Land", "latitude": 45.0, "longitude": 9.0},
        {"name": "Demo Town", "country": "Demo Land", "latitude": 41.9, "longitude": 12.5}]})


DEMO_FORECAST = {
    "utc_offset_seconds": 3600,
    "current": {"time": "2026-11-18T10:00", "temperature_2m": 14.2, "apparent_temperature": 12.8,
                "relative_humidity_2m": 71, "weather_code": 2, "wind_speed_10m": 11.0, "is_day": 1},
    "daily": {"time": ["2026-11-18", "2026-11-19", "2026-11-20", "2026-11-21", "2026-11-22"],
              "weather_code": [2, 61, 3, 0, 95],
              "temperature_2m_max": [16.1, 13.4, 14.0, 17.2, 12.5],
              "temperature_2m_min": [8.3, 9.0, 7.4, 6.9, 8.8],
              "precipitation_probability_max": [10, 80, 30, 0, 90]},
}
